INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_faostat', 'faostat', 'FAO FAOSTAT (agricultural trade)', 'intl_org', 'Global', NULL, 'Food and Agriculture Organization of the United Nations', 'https://www.fao.org/faostat/en/', 'faostatservices.fao.org/api/v1 returned 401 to my anonymous client - the REST API now appears to require a key/allowlist. Bulk CSV at bulks-faostat.fao.org is open and is the reliable ingestion path. Licence: CC BY 4.0.', 0);
