INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_wco', 'wco', 'World Customs Organization', 'intl_org', 'Global', NULL, 'World Customs Organization', 'https://www.wcoomd.org/', 'UNVERIFIED - every fetch to wcoomd.org failed at TCP/TLS level from this environment (TypeError: fetch failed), so no URL could be confirmed live. WCO publishes the HS nomenclature and an annual illicit-trade report but no open trade-value dataset or API. Recommend manual re-check of wcoomd.org/en/topics/nomenclature.', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_ilostat', 'ilostat', 'ILOSTAT (services and trade-related employment)', 'intl_org', 'Global', NULL, 'International Labour Organization - Department of Statistics', 'https://ilostat.ilo.org/', 'ilostat.ilo.org HTML returns 403 to automated clients (bot filter) but the machine endpoint rplumber.ilo.org/__docs__/ is open and documented (OpenAPI). Free, no key. Bulk CSV at ilostat.ilo.org/data/bulk (403 to bots, works in browser). Employment by economic activity covers services/commerce. Licence: CC BY 4.0.', 0);
