INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_cepii-baci', 'cepii-baci', 'CEPII BACI (reconciled bilateral trade)', 'intl_org', 'Global', NULL, 'Centre d''Etudes Prospectives et d''Informations Internationales', 'https://www.cepii.fr/CEPII/en/bdd_modele/bdd_modele_item.asp?id=37', 'Free bulk CSV after free registration. Derived from UN Comtrade with mirror-flow reconciliation (removes double counting, harmonises CIF/FOB). ~200 countries, 5000 products, 1995-present. No REST API - bulk zip only. Licence: free for research, citation required.', 0);
