INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_harvard-atlas', 'harvard-atlas', 'Harvard Growth Lab Atlas of Economic Complexity', 'intl_org', 'Global', NULL, 'Harvard Kennedy School Growth Lab', 'https://atlas.hks.harvard.edu/', 'Free GraphQL API (docs at github.com/harvard-growth-lab/api-docs/blob/main/atlas.md) plus free bulk CSV/DTA via Harvard Dataverse. Cleaned/reconciled Comtrade, 1962-present, HS and SITC. Licence: CC BY 4.0.', 0);
