INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_eurostat-comext', 'eurostat-comext', 'Eurostat COMEXT (EU international trade in goods)', 'intl_org', 'Europe', NULL, 'Eurostat - European Commission', 'https://ec.europa.eu/eurostat/web/international-trade-in-goods/database', 'Fully open, NO key. JSON-stat 2.0 + SDMX 2.1 + bulk TSV/SDMX files. Limit 50 categories/dimension and ~1M cells per query. Monthly CN8-level detail via COMEXT bulk. Licence: CC BY 4.0 (Eurostat re-use policy).', 0);
