INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_iea', 'iea', 'International Energy Agency (energy trade)', 'intl_org', 'Global', NULL, 'International Energy Agency', 'https://www.iea.org/data-and-statistics', 'UNVERIFIED - iea.org returns HTTP 403 to all automated clients (Cloudflare bot protection); loads normally in a browser. IEA energy-balance and oil/gas trade data are licensed (paid) for bulk; free interactive browsing only. Recommend a browser-based or authenticated check of iea.org/data-and-statistics/data-sets.', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_opec', 'opec', 'OPEC (crude oil and product trade)', 'intl_org', 'Global', NULL, 'Organization of the Petroleum Exporting Countries', 'https://www.opec.org/', 'Free. ASB published annually with downloadable XLSX/interactive tables; no REST API. Note opec.org/data-download.html and /data-graphs.html now 302 to the 404 page after the 2025 site redesign - only the ASB page resolves. Licence: free with attribution.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_opec_export_1', 'ent_opec', 'export', 1, 'https://www.opec.org/annual-statistical-bulletin.html', 'OPEC Annual Statistical Bulletin - crude and product exports', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_opec_import_1', 'ent_opec', 'import', 1, 'https://www.opec.org/annual-statistical-bulletin.html', 'ASB - crude and product imports by destination', 'html', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_irena', 'irena', 'IRENA (renewable energy trade and capacity)', 'intl_org', 'Global', NULL, 'International Renewable Energy Agency', 'https://www.irena.org/Data', 'UNVERIFIED - irena.org returns 403 to automated clients and pxweb.irena.org failed TLS/DNS from this environment. IRENASTAT normally exposes a PxWeb API (px-web JSON-stat) which would be the ingestion path once reachable. Recommend browser re-check of pxweb.irena.org/pxweb/en/IRENASTAT.', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_un-tourism', 'un-tourism', 'UN Tourism (formerly UNWTO) tourism statistics', 'intl_org', 'Global', NULL, 'World Tourism Organization (UN Tourism)', 'https://www.untourism.int/', 'REBRANDED: unwto.org now 301s to untourism.int, which returns 403 to automated clients. Tourism Statistics Database (inbound/outbound tourism receipts and expenditure = travel services trade) is subscription-based; free summary tables only. Could not verify a live fetchable URL - flagged for manual check.', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_us-census-trade', 'us-census-trade', 'US Census Bureau International Trade (USMCA/NAFTA reference)', 'intl_org', 'North America', 'USA', 'United States Census Bureau - Foreign Trade Division', 'https://usatradeonline.census.gov/', 'Census API free; key optional under 500 calls/day, free key for more. JSON. Monthly HS-10 detail. USITC DataWeb free with registration and has its own REST API. Licence: US public domain.', 0);
