INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_bis', 'bis', 'Bank for International Settlements', 'intl_org', 'Global', NULL, 'Bank for International Settlements - Monetary and Economic Department', 'https://data.bis.org/', 'MIGRATED: stats.bis.org web UI now 301s to data.bis.org, but the SDMX API lives at stats.bis.org/api/v2/ (SDMX-JSON 2.0 + SDMX-ML). Free, no key. Covers exchange rates, effective FX, credit, banking - relevant to trade finance not merchandise trade. Licence: free with attribution.', 0);
