INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_uneca', 'uneca', 'UNECA (Economic Commission for Africa)', 'regional_body', 'Africa', NULL, 'United Nations Economic Commission for Africa - African Centre for Statistics', 'https://ecastats.uneca.org/data/', 'Note the bare host ecastats.uneca.org serves only a meta-refresh; the canonical path is /data/ (http->https redirect loop if you request https://ecastats.uneca.org/data without trailing slash). Free, no key, no documented API. ECA also runs the ATPC trade policy database.', 0);
