INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_comesa', 'comesa', 'COMESA (Common Market for Eastern and Southern Africa)', 'regional_body', 'Africa', NULL, 'COMESA Secretariat - COMSTAT Data Hub', 'https://comstat.comesa.int/', 'COMSTAT runs on the Knoema/eGov platform: free browsing, CSV/XLSX export, embeddable widgets. NOTE the www. host (www.comstat.comesa.int) fails TLS - use the apex host comstat.comesa.int. Free.', 0);
