INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_apec', 'apec', 'APEC (StatsAPEC)', 'regional_body', 'Asia', NULL, 'APEC Secretariat / APEC Policy Support Unit', 'https://statistics.apec.org/', 'NOTE apec.org/publications/key-indicators-database now 404s - the live portal is statistics.apec.org (StatsAPEC). Free, no key, CSV/XLSX export. Covers all 21 APEC economies. No REST API.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_apec_export_1', 'ent_apec', 'export', 1, 'https://statistics.apec.org/', 'StatsAPEC Key Indicators Database - merchandise exports', 'html', 0);
