INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_saarc', 'saarc', 'SAARC (South Asian Association for Regional Cooperation)', 'regional_body', 'Asia', NULL, 'SAARC Secretariat', 'https://www.saarc-sec.org/', 'Minimal statistical function; SAARC does not run a data portal. Trade data for the region comes from member NSOs, SAWTEE and the ADB. HTML/PDF only, free.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_saarc_export_1', 'ent_saarc', 'export', 1, 'https://www.saarc-sec.org/', 'SAARC Secretariat - SAFTA trade documents', 'html', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_gcc-stat', 'gcc-stat', 'GCC Statistical Centre (GCC-Stat)', 'regional_body', 'Asia', NULL, 'Statistical Centre for the Cooperation Council for the Arab Countries of the Gulf', 'https://www.gccstat.org/', 'Only the apex host verified live; the /en/ locale path and /en/statistic/statistics/foreign-trade both returned 403/404 to my client. Arabic-first site. Free, XLSX/PDF bulletins, no API.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_gcc-stat_export_1', 'ent_gcc-stat', 'export', 1, 'https://www.gccstat.org/', 'GCC-Stat portal - foreign trade statistics', 'html', 0);
