INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_mercosur', 'mercosur', 'Mercosur (Southern Common Market)', 'regional_body', 'South America', NULL, 'Secretaria del MERCOSUR', 'https://www.mercosur.int/', 'NOTE mercosur.int apex 301s to www.mercosur.int - use the www host. Spanish/Portuguese. No statistical data portal or API; bloc trade data is best sourced from ALADI, CEPALSTAT or member NSOs (INDEC, IBGE). Free.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_mercosur_export_1', 'ent_mercosur', 'export', 1, 'https://www.mercosur.int/', 'Mercosur portal - commercial policy and trade statistics', 'html', 0);
