INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_andean-community', 'andean-community', 'Andean Community (CAN)', 'regional_body', 'South America', NULL, 'Secretaria General de la Comunidad Andina', 'https://www.comunidadandina.org/', 'PARTIAL - only the CAN homepage verified. The legacy statistics host estadisticas.comunidadandina.org is DEAD (NXDOMAIN) and every /estadisticas, /temas/estadistica and /documentos-estadisticos path returns 404 after the 2024-25 site rebuild. CAN now publishes via Tableau Public dashboards. Recommend locating the current SIICE URL manually.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_andean-community_export_1', 'ent_andean-community', 'export', 1, 'https://www.comunidadandina.org/', 'CAN portal - Sistema Integrado de Estadisticas de Comercio Exterior entry point', 'html', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_caricom', 'caricom', 'CARICOM (Caribbean Community)', 'regional_body', 'North America', NULL, 'CARICOM Secretariat - Regional Statistics Programme', 'https://statistics.caricom.org/', 'Free, no key. Databases published as XLSX/PDF plus a Redatam/PxWeb-style browser. Covers 15 member states. No REST API.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_caricom_export_1', 'ent_caricom', 'export', 1, 'https://statistics.caricom.org/', 'CARICOM Statistics - merchandise trade databases', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_caricom_import_1', 'ent_caricom', 'import', 1, 'https://statistics.caricom.org/', 'CARICOM Statistics - imports by member state', 'html', 0);
