INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_sica-sieca', 'sica-sieca', 'SICA / SIECA (Central American Economic Integration)', 'regional_body', 'North America', NULL, 'Secretaria de Integracion Economica Centroamericana (SIECA)', 'https://www.sieca.int/', 'estadisticas.sieca.int returns 200 but serves a JS-only SPA (no server-rendered content), so scraping requires a headless browser or the underlying XHR endpoints. Free, Spanish. Covers CA-5 + Panama + Dominican Republic.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_sica-sieca_export_1', 'ent_sica-sieca', 'export', 1, 'https://estadisticas.sieca.int/', 'SIECA statistics portal - Central American exports', 'html', 0);
