INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_spc-pacific', 'spc-pacific', 'Pacific Community (SPC) - Pacific Data Hub', 'regional_body', 'Oceania', NULL, 'Pacific Community - Statistics for Development Division', 'https://stats.pacificdata.org/', 'EXCELLENT for ingestion: open .Stat Suite SDMX 2.1 REST (SDMX-ML and SDMX-JSON), no key, no rate limit published. Covers 22 Pacific Island Countries and Territories. Licence: CC BY 4.0.', 0);
