INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_unescap', 'unescap', 'UNESCAP (Economic and Social Commission for Asia and the Pacific)', 'regional_body', 'Asia', NULL, 'United Nations ESCAP - Statistics Division', 'https://data.unescap.org/', 'Runs on Opendatasoft: free CSV/JSON/XLSX export and an Explore API per dataset (my probe of the generic /api/explore/v2.1/catalog/datasets path 404''d, so the API base differs - inspect a dataset page for its exact endpoint). No key for browsing. Licence: CC BY 3.0 IGO.', 0);
