INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_unece', 'unece', 'UNECE (Economic Commission for Europe)', 'regional_body', 'Europe', NULL, 'United Nations Economic Commission for Europe - Statistical Division', 'https://w3.unece.org/PXWeb/en', 'PxWeb backend means a machine-readable px-web JSON API is available per table (POST query to /PXWeb/api/v1/en/...). Free, no key. WARNING: a site banner states economic statistics indicators have not been updated since 1 May 2026 due to database restructuring - check freshness before ingesting.', 0);
