INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_uneclac-cepalstat', 'uneclac-cepalstat', 'UNECLAC / CEPAL (CEPALSTAT)', 'regional_body', 'South America', NULL, 'UN Economic Commission for Latin America and the Caribbean', 'https://statistics.cepal.org/portal/cepalstat/index.html?lang=en', 'CEPALSTAT exposes a documented public REST API (statistics.cepal.org/portal/cepalstat/api - JSON/XML, no key) alongside the UI; CSV/XLSX export per indicator. 33 LAC countries. Licence: free with attribution.', 0);
