INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_uneclac-cepalstat_import_1', 'ent_uneclac-cepalstat', 'import', 1, 'https://statistics.cepal.org/portal/cepalstat/index.html?lang=en', 'CEPALSTAT - imports of goods', 'html', 0);
