INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_unescwa_export_1', 'ent_unescwa', 'export', 1, 'https://data.unescwa.org/', 'ESCWA Data Portal - Arab region trade indicators', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_unescwa_import_1', 'ent_unescwa', 'import', 1, 'https://data.unescwa.org/', 'ESCWA Data Portal - imports', 'html', 0);
