INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_eaeu', 'eaeu', 'Eurasian Economic Union (EAEU)', 'regional_body', 'Europe', NULL, 'Eurasian Economic Commission - Statistics Department', 'https://eec.eaeunion.org/en/comission/department/dep_stat/', 'Free. Publishes monthly/annual XLSX bulletins on mutual trade (intra-EAEU) and external trade for the 5 members. Russian-first with English mirror. No API.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_eaeu_export_1', 'ent_eaeu', 'export', 1, 'https://eec.eaeunion.org/en/comission/department/dep_stat/', 'EEC Statistics Department - mutual and external trade statistics', 'html', 0);
