INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_commonwealth-secretariat', 'commonwealth-secretariat', 'Commonwealth Secretariat', 'regional_body', 'Global', NULL, 'Commonwealth Secretariat - Trade, Oceans and Natural Resources Directorate', 'https://thecommonwealth.org/', 'NOTE thecommonwealth.org/our-work/trade now 404s after the site redesign - only the root verified. Analytical publications (Commonwealth Trade Review, Trade Hot Topics) rather than a primary dataset; no API. Free.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_commonwealth-secretariat_export_1', 'ent_commonwealth-secretariat', 'export', 1, 'https://thecommonwealth.org/', 'Commonwealth Secretariat - trade competitiveness and Commonwealth Trade Review', 'html', 0);
