INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_usmca-usitc-dataweb', 'usmca-usitc-dataweb', 'USMCA statistical portals (USITC DataWeb)', 'regional_body', 'North America', NULL, 'United States International Trade Commission', 'https://dataweb.usitc.gov/', 'DataWeb: free registration, has a documented REST API (dataweb.usitc.gov/api) returning JSON, plus bulk query saving. Census API free with optional key. Canada (StatCan WDS) and Mexico (INEGI DENUE/BIE) APIs cover the other two parties - StatCan WDS timed out from this sandbox so it is not cited here. US data is public domain.', 0);
