INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_south-africa', 'south-africa', 'South Africa', 'country', 'Africa', 'ZAF', 'Statistics South Africa / South African Revenue Service', 'https://www.statssa.gov.za/', 'SARS is the legal compiler of merchandise trade and publishes monthly xlsx/csv bulk files from the trade-statistics landing page - programmatically ingestible. statssa.gov.za sits behind Imperva/Incapsula and returns a JS challenge to non-browser clients, so Stats SA releases (GDP, retail/wholesale trade) need a headless browser or manual mirroring.', 1);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_south-africa_export_1', 'ent_south-africa', 'export', 1, 'https://www.sars.gov.za/customs-and-excise/trade-statistics/', 'SARS merchandise trade statistics (exports)', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_south-africa_import_1', 'ent_south-africa', 'import', 1, 'https://www.sars.gov.za/customs-and-excise/trade-statistics/', 'SARS merchandise trade statistics (imports)', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_south-africa_commerce_1', 'ent_south-africa', 'commerce', 1, 'https://www.statssa.gov.za/', 'Stats SA GDP, retail & wholesale trade releases', 'html', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_egypt', 'egypt', 'Egypt', 'country', 'Africa', 'EGY', 'Central Agency for Public Mobilization and Statistics (CAPMAS)', 'https://www.capmas.gov.eg/', 'No public API. CAPMAS uses ASP.NET query-string paging; bulletins are pdf/xlsx behind page_id parameters. Central Bank of Egypt external-trade statistics page is blocked by its WAF for automated clients, so CAPMAS is the ingestion path; UN Comtrade recommended as a mirror.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_egypt_export_1', 'ent_egypt', 'export', 1, 'https://www.capmas.gov.eg/Pages/Publications.aspx?page_id=5104', 'CAPMAS publications - foreign trade bulletins', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_egypt_import_1', 'ent_egypt', 'import', 1, 'https://www.capmas.gov.eg/Pages/Publications.aspx?page_id=5104', 'CAPMAS publications - foreign trade bulletins', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_egypt_commerce_1', 'ent_egypt', 'commerce', 1, 'https://www.capmas.gov.eg/', 'CAPMAS statistical portal (national accounts, services)', 'html', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_nigeria', 'nigeria', 'Nigeria', 'country', 'Africa', 'NGA', 'National Bureau of Statistics (NBS)', 'https://nigerianstat.gov.ng/', 'NBS e-Library serves pdf + xlsx downloads per report id - bulk ingestible by scraping the e-library index. No documented API. statistics.cbn.gov.ng now 301-redirects to an unrelated /shop path and should not be used.', 1);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_nigeria_export_1', 'ent_nigeria', 'export', 1, 'https://nigerianstat.gov.ng/elibrary', 'NBS e-Library - Foreign Trade in Goods Statistics (quarterly)', 'xlsx', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_nigeria_import_1', 'ent_nigeria', 'import', 1, 'https://nigerianstat.gov.ng/elibrary', 'NBS e-Library - Foreign Trade in Goods Statistics (quarterly)', 'xlsx', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_nigeria_commerce_1', 'ent_nigeria', 'commerce', 1, 'https://nigerianstat.gov.ng/elibrary', 'NBS e-Library - GDP by economic activity (quarterly)', 'xlsx', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_nigeria_commerce_2', 'ent_nigeria', 'commerce', 2, 'https://www.cbn.gov.ng/', 'CBN statistical bulletin / economic reports', 'html', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_algeria', 'algeria', 'Algeria', 'country', 'Africa', 'DZA', 'Office National des Statistiques (ONS) / Direction Generale des Douanes', 'https://www.ons.dz/', 'Customs (Douanes) is the real compiler of merchandise trade; ONS republishes. Both roots verified live (ONS last updated 2 Sept 2026). Deep-link paths are SPIP query strings that change; crawl from the roots. No API, releases are pdf/xls.', 0);
