INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_ethiopia', 'ethiopia', 'Ethiopia', 'country', 'Africa', 'ETH', 'Ethiopian Statistical Service (ESS)', 'https://ess.gov.et/', 'The old host www.statsethiopia.gov.et no longer resolves (NXDOMAIN); the live portal is ess.gov.et (WordPress, 200). Trade data in Ethiopia is compiled by Customs and the National Bank of Ethiopia; ESS publishes pdf reports only. Recommend UN Comtrade as the machine-readable fallback.', 0);
