INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_morocco', 'morocco', 'Morocco', 'country', 'Africa', 'MAR', 'Office des Changes / Haut-Commissariat au Plan (HCP)', 'https://www.oc.gov.ma/en', 'Office des Changes (FX/trade authority), not the NSO, is the official publisher of Moroccan merchandise trade; it issues monthly xls/pdf ''Indicateurs des echanges exterieurs''. Only the site root verified 200 - the /en/etudes-et-statistiques/... deep paths returned 404, so crawl from the root. HCP covers national accounts/services.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_morocco_export_1', 'ent_morocco', 'export', 1, 'https://www.oc.gov.ma/en', 'Office des Changes - statistiques des echanges exterieurs (exports)', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_morocco_import_1', 'ent_morocco', 'import', 1, 'https://www.oc.gov.ma/en', 'Office des Changes - statistiques des echanges exterieurs (imports)', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_morocco_commerce_1', 'ent_morocco', 'commerce', 1, 'https://www.hcp.ma/', 'HCP - comptes nationaux, PIB par branche, indices d''activite', 'html', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_kenya', 'kenya', 'Kenya', 'country', 'Africa', 'KEN', 'Kenya National Bureau of Statistics (KNBS)', 'https://www.knbs.or.ke/', 'KNBS uses the Download Monitor plugin (dlm-version 5.0.23) - each report is a stable file URL, so bulk xlsx/pdf ingestion works by scraping /all-reports/. CBK publishes monthly trade series in xlsx. No REST API on either.', 1);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_kenya_export_1', 'ent_kenya', 'export', 1, 'https://www.knbs.or.ke/all-reports/', 'KNBS reports - Leading Economic Indicators / Economic Survey (exports)', 'xlsx', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_kenya_export_2', 'ent_kenya', 'export', 2, 'https://www.centralbank.go.ke/statistics/', 'CBK statistics - trade and balance of payments', 'xlsx', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_kenya_import_1', 'ent_kenya', 'import', 1, 'https://www.knbs.or.ke/all-reports/', 'KNBS reports - Leading Economic Indicators (imports)', 'xlsx', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_kenya_import_2', 'ent_kenya', 'import', 2, 'https://www.centralbank.go.ke/statistics/', 'CBK statistics - imports by category', 'xlsx', 0);
