INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_angola', 'angola', 'Angola', 'country', 'Africa', 'AGO', 'Instituto Nacional de Estatistica (INE) / Banco Nacional de Angola', 'https://www.bna.ao/', 'INE Angola (ine.gov.ao and www.ine.gov.ao) failed to connect on repeated attempts - portal effectively offline/unreachable from outside, likely TLS or host failure. Banco Nacional de Angola is used as the working publisher. Fall back to UN Comtrade for HS-level merchandise detail.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_angola_export_1', 'ent_angola', 'export', 1, 'https://www.bna.ao/', 'BNA - estatisticas do sector externo (exportacoes)', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_angola_import_1', 'ent_angola', 'import', 1, 'https://www.bna.ao/', 'BNA - estatisticas do sector externo (importacoes)', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_angola_commerce_1', 'ent_angola', 'commerce', 1, 'https://www.bna.ao/', 'BNA - boletim estatistico / contas externas', 'html', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_tanzania', 'tanzania', 'Tanzania', 'country', 'Africa', 'TZA', 'National Bureau of Statistics (NBS Tanzania)', 'https://www.nbs.go.tz/', 'Bank of Tanzania publishes the timeliest monthly goods trade series (Monthly Economic Review, pdf + xlsx annexes); NBS publishes annual/quarterly trade and national accounts in xlsx. No API.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_tanzania_export_1', 'ent_tanzania', 'export', 1, 'https://www.nbs.go.tz/', 'NBS Tanzania - foreign trade statistics', 'html', 0);
