INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_tanzania_import_1', 'ent_tanzania', 'import', 1, 'https://www.nbs.go.tz/', 'NBS Tanzania - foreign trade statistics', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_tanzania_import_2', 'ent_tanzania', 'import', 2, 'https://www.bot.go.tz/', 'Bank of Tanzania - Monthly Economic Review (imports)', 'pdf', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_tanzania_commerce_1', 'ent_tanzania', 'commerce', 1, 'https://www.nbs.go.tz/', 'NBS Tanzania - National Accounts / GDP by activity', 'xlsx', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_cote-divoire', 'cote-divoire', 'Cote d''Ivoire', 'country', 'Africa', 'CIV', 'Institut National de la Statistique (INS) / BCEAO', 'https://www.bceao.int/', 'www.ins.ci failed to connect at verification (unreachable). Per rule 3, the central bank (BCEAO, the shared WAEMU central bank) is used as the real publisher - it issues monthly/annual trade and BoP series per member state in pdf/xls via its statistical database. UN Comtrade recommended as HS-level fallback.', 1);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_cote-divoire_export_1', 'ent_cote-divoire', 'export', 1, 'https://www.bceao.int/', 'BCEAO - statistiques du commerce exterieur (UEMOA/Cote d''Ivoire)', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_cote-divoire_import_1', 'ent_cote-divoire', 'import', 1, 'https://www.bceao.int/', 'BCEAO - importations', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_cote-divoire_commerce_1', 'ent_cote-divoire', 'commerce', 1, 'https://www.bceao.int/', 'BCEAO - comptes nationaux et indicateurs economiques', 'html', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_ghana', 'ghana', 'Ghana', 'country', 'Africa', 'GHA', 'Ghana Statistical Service', 'https://statsghana.gov.gh/', 'No API. GSS relaunched on a Next.js site in 2026; trade and GDP releases are pdf + xlsx under /data-statistics/*. GSS''s own StatsBank portal (https://statsbank.statsghana.gov.gh/) FAILED TO CONNECT at verification - do not depend on it for ingestion. Bank of Ghana is the timeliest publisher (monthly merchandise exports/imports in the Statistical Bulletin and the economic-data time series); Ghana Revenue Authority customs data is not published openly. UN Comtrade for HS-level detail.', 1);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_ghana_export_1', 'ent_ghana', 'export', 1, 'https://statsghana.gov.gh/data-statistics/business-industry-and-trade-statistics', 'GSS Business, Industry & Trade Statistics (merchandise exports)', 'html', 0);
