INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_ghana_export_3', 'ent_ghana', 'export', 3, 'https://www.bog.gov.gh/economic-data/', 'Bank of Ghana economic data - external sector time series', 'xlsx', 0);
