INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_ghana_commerce_1', 'ent_ghana', 'commerce', 1, 'https://statsghana.gov.gh/data-statistics/economic-statistics', 'GSS Economic Statistics - quarterly GDP by economic activity, services', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_ghana_commerce_2', 'ent_ghana', 'commerce', 2, 'https://statsghana.gov.gh/publications/monthly-wrap-and-policy-brief', 'GSS Monthly Wrap & Policy Brief', 'pdf', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_dr-congo', 'dr-congo', 'DR Congo', 'country', 'Africa', 'COD', 'Institut National de la Statistique (INS-RDC) / Banque Centrale du Congo', 'https://www.bcc.cd/', 'www.ins-rdc.org returns HTTP 403 to automated clients (WAF/bot block) - probably reachable in a browser but not ingestible, so it is excluded. Banque Centrale du Congo publishes the weekly ''Condense d''informations statistiques'' with trade aggregates in pdf/xls. Use UN Comtrade for HS detail.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_dr-congo_export_1', 'ent_dr-congo', 'export', 1, 'https://www.bcc.cd/', 'BCC - condense d''informations statistiques (exportations)', 'pdf', 0);
