INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_uganda', 'uganda', 'Uganda', 'country', 'Africa', 'UGA', 'Uganda Bureau of Statistics (UBOS)', 'https://www.ubos.org/', 'UBOS publishes downloadable xlsx datasets under /explore-statistics/ (numbered topic ids); Bank of Uganda mirrors monthly trade in its statistics section. No REST API.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_uganda_export_1', 'ent_uganda', 'export', 1, 'https://www.ubos.org/explore-statistics/', 'UBOS statistics explorer - external trade statistics', 'xlsx', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_uganda_export_2', 'ent_uganda', 'export', 2, 'https://www.bou.or.ug/', 'Bank of Uganda - trade statistics / BoP', 'xlsx', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_uganda_import_1', 'ent_uganda', 'import', 1, 'https://www.ubos.org/explore-statistics/', 'UBOS statistics explorer - imports', 'xlsx', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_uganda_import_2', 'ent_uganda', 'import', 2, 'https://www.bou.or.ug/', 'Bank of Uganda - imports data', 'xlsx', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_uganda_commerce_1', 'ent_uganda', 'commerce', 1, 'https://www.ubos.org/explore-statistics/', 'UBOS - GDP by economic activity / national accounts', 'xlsx', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_tunisia', 'tunisia', 'Tunisia', 'country', 'Africa', 'TUN', 'Institut National de la Statistique (INS Tunisie)', 'https://www.ins.tn/en', 'INS serves numbered statistics pages that render HTML tables plus xls/csv export buttons - the most machine-readable African NSO in this set after ABS/StatsNZ. Quarterly GDP releases confirmed current (Q2 2026 published 15-08-2026).', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_tunisia_export_1', 'ent_tunisia', 'export', 1, 'https://www.ins.tn/en/statistiques/57', 'INS - foreign trade statistics tables (exports)', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_tunisia_import_1', 'ent_tunisia', 'import', 1, 'https://www.ins.tn/en/statistiques/57', 'INS - foreign trade statistics tables (imports)', 'html', 0);
