INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_cameroon', 'cameroon', 'Cameroon', 'country', 'Africa', 'CMR', 'Institut National de la Statistique (INS Cameroun)', 'https://ins-cameroun.cm/', 'Site root verified live (French, WordPress). Trade is compiled jointly with the Directorate General of Customs and published in the annual statistical yearbook and quarterly notes (pdf/xls). BEAC (regional central bank) also publishes Cameroon trade aggregates. No API - UN Comtrade recommended for HS-level.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_cameroon_export_1', 'ent_cameroon', 'export', 1, 'https://ins-cameroun.cm/', 'INS Cameroun - commerce exterieur / annuaire statistique', 'pdf', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_cameroon_import_1', 'ent_cameroon', 'import', 1, 'https://ins-cameroun.cm/', 'INS Cameroun - importations', 'pdf', 0);
