INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_libya', 'libya', 'Libya', 'country', 'Africa', 'LBY', 'Central Bank of Libya (Bureau of Statistics portal offline)', 'https://cbl.gov.ly/en/', 'CRITICAL: the Libyan Bureau of Statistics and Census domain bsc.ly is no longer a government site - it now serves an online-casino squatter page. There is no working national statistics portal. Central Bank of Libya is the only live official publisher (verified 200). Use UN Comtrade / IMF DOTS for Libyan merchandise trade.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_libya_export_1', 'ent_libya', 'export', 1, 'https://cbl.gov.ly/en/', 'CBL economic bulletin - oil and non-oil exports', 'pdf', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_libya_import_1', 'ent_libya', 'import', 1, 'https://cbl.gov.ly/en/', 'CBL economic bulletin - imports / letters of credit', 'pdf', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_libya_commerce_1', 'ent_libya', 'commerce', 1, 'https://cbl.gov.ly/en/', 'CBL annual/quarterly economic bulletin', 'pdf', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_zambia', 'zambia', 'Zambia', 'country', 'Africa', 'ZMB', 'Zambia Statistics Agency (ZamStats)', 'https://www.zamstats.gov.zm/', 'ZamStats is unusually current - the homepage published July 2026 trade balance (K4.1bn surplus) at verification time. Monthly bulletins come as pdf plus xlsx annexes; no API. Bank of Zambia supplements with BoP.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_zambia_export_1', 'ent_zambia', 'export', 1, 'https://www.zamstats.gov.zm/economic-statistics/', 'ZamStats economic statistics - monthly external trade', 'xlsx', 0);
