INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_zambia_import_1', 'ent_zambia', 'import', 1, 'https://www.zamstats.gov.zm/economic-statistics/', 'ZamStats economic statistics - imports', 'xlsx', 0);
