INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_senegal', 'senegal', 'Senegal', 'country', 'Africa', 'SEN', 'Agence Nationale de la Statistique et de la Demographie (ANSD)', 'https://www.ansd.sn/', 'ANSD /publications verified 200 (Drupal listing, pdf + some xlsx). /statistiques/economie returns 404 - do not use. BCEAO carries the harmonised WAEMU trade series for Senegal.', 0);
