INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_australia', 'australia', 'Australia', 'country', 'Oceania', 'AUS', 'Australian Bureau of Statistics (ABS)', 'https://www.abs.gov.au/', 'Best-in-class: ABS releases csv/xlsx time-series data cubes with every release AND offers the ABS Data API (SDMX-JSON) at data.api.abs.gov.au - note the API root path itself returns 403, calls must target /rest/data/{dataflow}/... Release calendar confirmed live through Feb 2027.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_australia_export_1', 'ent_australia', 'export', 1, 'https://www.abs.gov.au/statistics/economy/international-trade/international-trade-goods', 'International Trade in Goods (monthly) - exports', 'xlsx', 0);
