INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_new-zealand', 'new-zealand', 'New Zealand', 'country', 'Oceania', 'NZL', 'Stats NZ / Tatauranga Aotearoa', 'https://www.stats.govt.nz/', 'Monthly overseas merchandise trade published with csv/xlsx downloads. Bulk time series live in Infoshare (infoshare.stats.govt.nz) and NZ.Stat, which require a session cookie (the Infoshare root 302-redirects with AspxAutoDetectCookieSupport), so scripted ingestion should use the release-page csv links rather than Infoshare.', 0);
