INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_papua-new-guinea', 'papua-new-guinea', 'Papua New Guinea', 'country', 'Oceania', 'PNG', 'National Statistical Office of Papua New Guinea', 'https://www.nso.gov.pg/', 'NSO PNG is a WordPress site using the WPFD file-directory plugin: publications are pdf/xlsx under /documents/. The IMTS release is dated (latest listed release page is the 2020 release), so Bank of PNG Quarterly Economic Bulletin and SPC Pacific Data Hub are better for recency.', 0);
