INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_new-caledonia', 'new-caledonia', 'New Caledonia', 'country', 'Oceania', 'NCL', 'Institut de la statistique et des etudes economiques (ISEE-NC)', 'https://isee.nc/', 'ISEE publishes customs-based SCIM series with downloadable xls tables by HS customs code (confidential cells marked ''x''). Note the site canonicalises to isee.nc (www.isee.nc 301s) and its sitemap.xml erroneously emits https://localhost/ hostnames - use the slugs against isee.nc. No API.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_new-caledonia_export_1', 'ent_new-caledonia', 'export', 1, 'https://isee.nc/echanges-exterieurs', 'ISEE - echanges exterieurs, exportations (SCIM)', 'xlsx', 0);
