INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_french-polynesia', 'french-polynesia', 'French Polynesia', 'country', 'Oceania', 'PYF', 'Institut de la statistique de la Polynesie francaise (ISPF)', 'https://www.ispf.pf/', 'ISPF exposes clean theme URLs (/themes/comext, /themes/pib) plus a /data section and /publication?theme=... filter; tables download as xls/csv. Verified via the site''s own sitemap.xml. No API.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_french-polynesia_export_1', 'ent_french-polynesia', 'export', 1, 'https://www.ispf.pf/themes/comext', 'ISPF - theme Commerce exterieur (exportations)', 'xlsx', 0);
