INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_vanuatu', 'vanuatu', 'Vanuatu', 'country', 'Oceania', 'VUT', 'Vanuatu Bureau of Statistics (VNSO)', 'https://vnso.gov.vu/index.php/en/', 'Joomla site; the root redirects to /index.php/en/ (use that exact URL). Guessed topic paths (/statistics-by-topic/trade, /economic-statistics) all return 404, so only the verified root is cited - crawl its menu. VNSO publishes monthly trade xlsx and also syndicates to SPC''s SDMX hub.', 0);
