INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_samoa', 'samoa', 'Samoa', 'country', 'Oceania', 'WSM', 'Samoa Bureau of Statistics', 'https://www.sbs.gov.ws/', 'Verified: /trade-imports-exports/ lists monthly Merchandise Trade Report pdfs (file URLs under /digi/). The site also has /national-accounts/, /economy/ and /import-price-index/ pages listed in its wp-sitemap (not individually fetched). Mostly pdf - low machine-readability; prefer SPC SDMX for ingestion.', 0);
