INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_tonga', 'tonga', 'Tonga', 'country', 'Oceania', 'TON', 'Tonga Statistics Department', 'https://tongastats.gov.to/', 'Verified live and actively maintained (foreign-trade page last modified July 2026). WordPress with the WPFD file-directory plugin - downloads are xlsx/pdf under stable file URLs, scrapeable. Sub-pages /national-accounts/ and /balance-of-payments/ also exist per the site sitemap.', 0);
