INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_micronesia', 'micronesia', 'Micronesia (Federated States of)', 'country', 'Oceania', 'FSM', 'FSM Division of Statistics (portal unreachable) / SPC Pacific Data Hub', 'https://stats.pacificdata.org/', 'The FSM Division of Statistics site (fsmstatistics.fm and www.fsmstatistics.fm) FAILED TO CONNECT on repeated attempts - treat as offline. SPC''s Pacific Data Hub is the authoritative regional mirror and exposes a genuine SDMX 2.1 REST API (verified: /rest/dataflow/SPC returns application/vnd.sdmx.structure+xml). Note the endpoint rejects ?format=sdmx-json with 406 - use Accept headers instead.', 0);
