INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_india', 'india', 'India', 'country', 'Asia', 'IND', 'Ministry of Commerce & Industry (TRADESTAT / DGCI&S); MoSPI', 'https://tradestat.commerce.gov.in/eidb/commodity_wise_export', 'No public REST API. TRADESTAT is a session-based ASP.NET form app (POST queries, session cookie + no-back JS); requires form-post scraping. Root https://tradestat.commerce.gov.in/ 302-redirects to /eidb/commodity_wise_export.', 0);
