INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_netherlands', 'netherlands', 'Netherlands', 'country', 'Europe', 'NLD', 'Centraal Bureau voor de Statistiek (CBS) - StatLine OpenData', 'https://opendata.cbs.nl/ODataCatalog/Tables?$format=json', 'CBS OpenData is fully keyless OData v3: /ODataApi/odata/{id}/TypedDataSet, /UntypedDataSet, /TableInfos. English tables end in ENG. Catalogue supports $filter=substringof(''International trade'',Title). Other useful ids found: 84668ENG (trade & transit by transport mode), 85427ENG/85428ENG (goods, change of ownership).', 0);
