INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_poland', 'poland', 'Poland', 'country', 'Europe', 'POL', 'Statistics Poland (GUS) - Local Data Bank (BDL)', 'https://stat.gov.pl/en/', 'BDL API v1 (bdl.stat.gov.pl/api/v1) is keyless with rate limits; a free X-ClientId raises quotas. Paged JSON with HAL-style links. Note: /en/topics/prices-trade/foreign-trade/ is 404 - the valid parent path is /en/topics/prices-trade/.', 0);
