INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_denmark', 'denmark', 'Denmark', 'country', 'Europe', 'DNK', 'Statistics Denmark (Danmarks Statistik) - StatBank', 'https://www.statbank.dk/statbank5a/default.asp?w=1920', 'StatBank REST API (api.statbank.dk/v1: subjects, tables, tableinfo, data) is keyless; ?lang=en for English but subject descriptions returned Danish at /v1/subjects. Verified /v1/tableinfo/UHV1?lang=en - note UHV1 is flagged "active": false (discontinued), so resolve the current external-trade table id via /v1/tables before ingesting. Current API build 1.7.0 (11 May 2026).', 0);
