INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_united-states', 'united-states', 'United States', 'country', 'North America', 'USA', 'U.S. Census Bureau Foreign Trade Division, USITC and BEA', 'https://www.census.gov/foreign-trade/data/index.html', 'Census International Trade API is free with a registered key at api.census.gov; endpoints /data/timeseries/intltrade/exports/hs and /imports/hs, monthly, HS10 detail, district and country dimensions. BEA API (apps.bea.gov/api/data) is free with a key and serves ITA (international services trade) and GDPbyIndustry datasets. USITC DataWeb requires a free login for bulk pulls but has a documented REST endpoint.', 1);
