INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_canada', 'canada', 'Canada', 'country', 'North America', 'CAN', 'Statistics Canada', 'https://www.statcan.gc.ca/en/developers/wds/user-guide', 'StatCan WDS is a free, keyless REST API (base https://www150.statcan.gc.ca/t1/wds/rest/). getFullTableDownloadCSV/{productId}/en returns a zipped CSV of any table; getDataFromVectorsAndLatestNPeriods for series pulls. Note: the WDS endpoint timed out for my fetcher during verification while the documented user guide and table pages resolved 200 - throttle and retry with a real user agent.', 0);
