INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_panama', 'panama', 'Panama', 'country', 'North America', 'PAN', 'Instituto Nacional de Estadistica y Censo (INEC), Contraloria General', 'https://www.inec.gob.pa/', 'No API. INEC publishes ASP.NET-driven Excel cuadros; the Default3.aspx category/subcategory IDs are stable deep links and both verified live. Category-to-topic mapping should be re-checked on ingest since the page titles render client-side.', 0);
