INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_cuba', 'cuba', 'Cuba', 'country', 'North America', 'CUB', 'Oficina Nacional de Estadistica e Informacion (ONEI) - site unreachable; UN Comtrade fallback', 'https://comtradeplus.un.org/', 'NO WORKING NATIONAL SOURCE. www.onei.gob.cu, onei.gob.cu and /node/ deep links all failed connection (TLS/network) on 2026-09-04 from three attempts. Cuba also reports irregularly to Comtrade, so partner-mirror statistics are the practical source.', 0);
