INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_el-salvador', 'el-salvador', 'El Salvador', 'country', 'North America', 'SLV', 'Banco Central de Reserva de El Salvador (BCR)', 'https://www.bcr.gob.sv/', 'BCR migrated to a WordPress front end whose REST API returns 401 to anonymous callers; legacy https://www.bcr.gob.sv/bcrsite/?cat=1000 now serves a redirect notice page. Trade tables live behind the Estadisticas section as Excel. SIECA is the reliable machine-readable complement.', 0);
