INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_trinidad-and-tobago', 'trinidad-and-tobago', 'Trinidad and Tobago', 'country', 'North America', 'TTO', 'Central Statistical Office (CSO)', 'https://cso.gov.tt/subjects/international-trade/', 'CSO is WordPress - https://cso.gov.tt/wp-json/wp/v2/pages?search=trade is open and useful for automated link discovery. The ''INTERNATIONAL TRADE PORTAL'' page 301-redirects to a Eurotrace instance at http://csottwebtext.gov.tt:8001/eurotrace/mainxtnet.do (non-TLS, non-standard port) so it is not listed as a verified URL.', 0);
