INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_jamaica', 'jamaica', 'Jamaica', 'country', 'North America', 'JAM', 'Statistical Institute of Jamaica (STATIN)', 'https://statinja.gov.jm/', 'No API. STATIN is ASP.NET; the correct trade path is /Trade-Econ%20Statistics/InternationalMerchandiseTrade/newtrade.aspx (the older NewInternationalMerchandiseTrade.aspx now 404s). Tables are downloadable Excel behind each tab.', 0);
