INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_nicaragua', 'nicaragua', 'Nicaragua', 'country', 'North America', 'NIC', 'Banco Central de Nicaragua (bot-walled) - SIECA and UN Comtrade fallback', 'https://estadisticas.sieca.int/', 'NO DIRECT NATIONAL SOURCE VERIFIABLE. Both https://www.bcn.gob.ni/ and /estadisticas-economicas redirect to a Radware validate.perfdrive.com bot challenge, so BCN cannot be crawled headlessly; a browser session is required. SIECA and Comtrade are the practical machine sources.', 0);
