INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_haiti', 'haiti', 'Haiti', 'country', 'North America', 'HTI', 'Institut Haitien de Statistique et d''Informatique (IHSI)', 'https://ihsi.gouv.ht/', 'Thin national office. IHSI home is live but its WordPress REST route (/wp-json/wp/v2/pages) returns 404, and no deep trade page could be verified; trade data is largely produced by BRH and AGD and released as PDF. Use UN Comtrade partner-mirror data as the reliable series.', 0);
