INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_bahamas', 'bahamas', 'Bahamas', 'country', 'North America', 'BHS', 'Central Bank of The Bahamas (Dept. of Statistics site blocks bots)', 'https://www.centralbankbahamas.com/statistics', 'Thin/blocked national office: https://www.bahamas.gov.bs/statistics and the government portal statistics path both return 403 to automated clients, and bnsibahamas.com does not resolve. Central Bank digests plus CARICOM/Comtrade are the workable sources.', 0);
