INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_barbados', 'barbados', 'Barbados', 'country', 'North America', 'BRB', 'Barbados Statistical Service (BSS)', 'https://stats.gov.bb/', 'Thin office, no API, but the site is WordPress so https://stats.gov.bb/wp-json/wp/v2/pages?search=trade is open and returns the canonical trade page link - useful for automated link refresh. CARICOM and Comtrade recommended as fallbacks.', 0);
