INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_brazil', 'brazil', 'Brazil', 'country', 'South America', 'BRA', 'MDIC / Comex Stat and IBGE', 'https://comexstat.mdic.gov.br/en/home', 'Comex Stat is free and public with a JSON backend at https://api-comexstat.mdic.gov.br/general (returned HTTP 401 to a bare GET during verification - it expects a POST/query payload and a referer, so it is live but not a plain URL). Annual bulk NCM CSVs live under https://balanca.economia.gov.br/balanca/bd/comexstat-bd/ncm/ which returned 403 to my fetcher (browser UA required). IBGE SIDRA (apisidra.ibge.gov.br, servicodados.ibge.gov.br/api/v3/agregados) and www.ibge.gov.br returned HTTP 503 to every attempt on 2026-09-04, so IBGE URLs are deliberately EXCLUDED as unverified - retry later; SIDRA is normally free and keyless and covers PMC retail and PMS services.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_brazil_export_1', 'ent_brazil', 'export', 1, 'https://comexstat.mdic.gov.br/en/home', 'Comex Stat exports query and bulk download (English)', 'api', 0);
