INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_brazil_import_1', 'ent_brazil', 'import', 1, 'https://comexstat.mdic.gov.br/en/home', 'Comex Stat imports query and bulk download (English)', 'api', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_brazil_import_2', 'ent_brazil', 'import', 2, 'https://comexstat.mdic.gov.br/en/geral', 'Comex Stat general query builder - imports (English)', 'csv', 0);
