INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_argentina', 'argentina', 'Argentina', 'country', 'South America', 'ARG', 'INDEC and Datos Argentina series API', 'https://www.indec.gob.ar/indec/web/Nivel4-Tema-3-2-40', 'apis.datos.gob.ar/series/api/series/ is free and keyless and returned live JSON during verification (note the TRAILING SLASH before the query string - without it you get a 301). INDEC itself publishes zipped CSV/XLS per release. comexdata.indec.gob.ar did not resolve in DNS on 2026-09-04.', 0);
