INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_colombia', 'colombia', 'Colombia', 'country', 'South America', 'COL', 'DANE (bot-blocked) via Datos Abiertos Colombia and Banco de la Republica', 'https://www.datos.gov.co/browse?q=exportaciones', 'DANE is the true NSO but www.dane.gov.co and microdatos.dane.gov.co both returned HTTP 403 to non-browser clients on 2026-09-04, so no DANE URL is listed as verified. datos.gov.co is a Socrata instance: every dataset exposes https://www.datos.gov.co/resource/{4x4}.json with SoQL filters, free, optional app token - this is the best programmatic route to DANE/DIAN trade tables.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_colombia_export_1', 'ent_colombia', 'export', 1, 'https://www.datos.gov.co/browse?q=exportaciones', 'Datos Abiertos Colombia (Socrata) - DANE/DIAN export datasets (Spanish)', 'api', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_colombia_export_2', 'ent_colombia', 'export', 2, 'https://totoro.banrep.gov.co/estadisticas-economicas/', 'Banco de la Republica economic statistics - trade series (Spanish)', 'xlsx', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_colombia_import_1', 'ent_colombia', 'import', 1, 'https://www.datos.gov.co/browse?q=exportaciones', 'Datos Abiertos Colombia - import datasets via Socrata (Spanish)', 'api', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_colombia_import_2', 'ent_colombia', 'import', 2, 'https://totoro.banrep.gov.co/estadisticas-economicas/', 'Banrep balance of payments and imports (Spanish)', 'xlsx', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_colombia_commerce_1', 'ent_colombia', 'commerce', 1, 'https://totoro.banrep.gov.co/estadisticas-economicas/', 'Banrep GDP by economic activity and services (Spanish)', 'xlsx', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_chile', 'chile', 'Chile', 'country', 'South America', 'CHL', 'Servicio Nacional de Aduanas and Banco Central de Chile', 'https://www.aduana.cl/aduana/site/edic/base/port/inicio.html', 'Banco Central de Chile offers a free SOAP/REST web service over the SIETE database requiring free registration (user + password passed as query params); the documented index pages si3.bcentral.cl/estadisticas/Principal1/Web_Services/index*.htm 302-redirect to an ErrorPage, and www.bcentral.cl is behind Incapsula, so only https://si3.bcentral.cl/siete verified. Aduanas publishes annual/monthly customs microdata (DIN/DUS files) from the portal; all deep 2016/2018-dated stat URLs I tried returned 404 - crawl from the portal root.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_chile_export_1', 'ent_chile', 'export', 1, 'https://si3.bcentral.cl/siete', 'Banco Central SIETE statistics database - exports (Spanish)', 'api', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_chile_export_2', 'ent_chile', 'export', 2, 'https://www.aduana.cl/aduana/site/edic/base/port/inicio.html', 'Aduanas de Chile portal - foreign trade statistics (Spanish)', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_chile_import_1', 'ent_chile', 'import', 1, 'https://si3.bcentral.cl/siete', 'Banco Central SIETE - imports series (Spanish)', 'api', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_chile_import_2', 'ent_chile', 'import', 2, 'https://www.aduana.cl/aduana/site/edic/base/port/inicio.html', 'Aduanas customs import records (Spanish)', 'html', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_chile_commerce_1', 'ent_chile', 'commerce', 1, 'https://si3.bcentral.cl/siete', 'SIETE - IMACEC, GDP and GDP by activity (Spanish)', 'api', 0);
INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_peru', 'peru', 'Peru', 'country', 'South America', 'PER', 'SUNAT (customs), INEI and BCRP', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/', 'BCRP exposes a free keyless series API at https://estadisticas.bcrp.gob.pe/estadisticas/series/api/{series}/json/{start}/{end} - the best machine route for Peru. SUNAT publishes customs Excel; https://www.sunat.gob.pe/estad-comExterior/ is dead (404), use /estadisticasestudios/. INEI content is mostly PDF/XLS.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_peru_export_1', 'ent_peru', 'export', 1, 'https://estadisticas.bcrp.gob.pe/estadisticas/series/', 'BCRP statistical series - exports (Spanish)', 'api', 0);
