INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_peru_import_1', 'ent_peru', 'import', 1, 'https://estadisticas.bcrp.gob.pe/estadisticas/series/', 'BCRP series - imports by use (Spanish)', 'api', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_peru_import_2', 'ent_peru', 'import', 2, 'https://www.sunat.gob.pe/estadisticasestudios/', 'SUNAT import statistics (Spanish)', 'xlsx', 0);
