INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_ecuador', 'ecuador', 'Ecuador', 'country', 'South America', 'ECU', 'Banco Central del Ecuador and SENAE (Aduana del Ecuador)', 'https://www.bce.fin.ec/', 'BCE relaunched on WordPress in 2024-2025 and broke its legacy paths: /informacioneconomica/comercio-exterior 301s to a news article, /informacion-estadistica/ 404s, and contenido.bce.fin.ec JSP endpoints redirect through a bce_url wrapper. Only the root verified. No API; statistical bulletins are Excel/PDF. The BCE WordPress REST API (/wp-json/wp/v2/pages?search=) is open and usable for link discovery.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_ecuador_export_1', 'ent_ecuador', 'export', 1, 'https://www.bce.fin.ec/', 'BCE statistical information - exports / trade balance (Spanish)', 'xlsx', 0);
