INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_ecuador_import_1', 'ent_ecuador', 'import', 1, 'https://www.bce.fin.ec/', 'BCE statistical information - imports (Spanish)', 'xlsx', 0);
