INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_venezuela', 'venezuela', 'Venezuela', 'country', 'South America', 'VEN', 'Banco Central de Venezuela (BCV)', 'https://www.bcv.org.ve/estadisticas/comercio-exterior', 'INE Venezuela (www.ine.gov.ve) does not resolve in DNS. BCV publishes irregular Excel series and its /estadisticas/agregados-macroeconomicos path 404s. Data is heavily lagged - rely on UN Comtrade mirror statistics for current-year trade.', 0);
