INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_uruguay', 'uruguay', 'Uruguay', 'country', 'South America', 'URY', 'Instituto Nacional de Estadistica (INE) and Banco Central del Uruguay', 'https://www.gub.uy/instituto-nacional-estadistica/datos-y-estadisticas/estadisticas', 'No dedicated trade API. INE publishes CSV/XLS through the gub.uy platform (which also has a catalogo.datos.gub.uy CKAN instance worth adding later); BCU publishes Excel series. Customs (DNA) operates a separate portal not verified here.', 0);
