INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_bolivia', 'bolivia', 'Bolivia', 'country', 'South America', 'BOL', 'Instituto Nacional de Estadistica (INE Bolivia)', 'https://www.ine.gob.bo/index.php/estadisticas-economicas/comercio-exterior/', 'No API; INE Bolivia serves XLSX/CSV per indicator from Joomla category pages. Sub-paths below /comercio-exterior/ (e.g. /exportaciones-nacionales/) return 404 - crawl the category page for current file links.', 0);
