INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_paraguay', 'paraguay', 'Paraguay', 'country', 'South America', 'PRY', 'Banco Central del Paraguay, INE Paraguay and DNIT (customs)', 'https://www.bcp.gov.py/', 'No API. BCP deep links of the form /...-iNNN are numeric and unstable (both /comercio-exterior-i370 and /informe-de-comercio-exterior-i385 returned 404), so only the root is listed. Paraguayan customs moved from www.aduana.gov.py to DNIT (www.dnit.gov.py) in 2023-24 - the old domain 302s there.', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_paraguay_export_1', 'ent_paraguay', 'export', 1, 'https://www.bcp.gov.py/', 'BCP statistical annex - exports / external trade report (Spanish)', 'xlsx', 0);
INSERT INTO entity_sources (id, entity_id, category, slot, url, label, fmt, tls_warning) VALUES ('src_paraguay_export_2', 'ent_paraguay', 'export', 2, 'https://www.dnit.gov.py/web/portal-institucional/', 'DNIT (ex-Aduanas) institutional portal - customs statistics (Spanish)', 'html', 0);
