INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_guyana', 'guyana', 'Guyana', 'country', 'South America', 'GUY', 'Bureau of Statistics Guyana', 'https://statisticsguyana.gov.gy/', 'WordPress site with an open REST API - https://statisticsguyana.gov.gy/wp-json/wp/v2/pages?search=trade reliably enumerates current external-trade release pages (verified: returns 2026 year-to-date import releases). Note /subjects/economy/external-trade/ 404s; the live prefix is /subjects/external-trade/. No statistical API; XLSX/PDF releases.', 0);
