INSERT INTO entities (id, slug, name, kind, continent, iso3, agency_name, homepage, api_notes, is_active) VALUES ('ent_suriname', 'suriname', 'Suriname', 'country', 'South America', 'SUR', 'Algemeen Bureau voor de Statistiek (General Bureau of Statistics)', 'https://statistics-suriname.org/', 'Thin office, no API. Bilingual site (English/Dutch); English paths verified. WordPress REST (/wp-json/wp/v2/pages?search=export) is open and is the cheapest way to refresh links. Use CARICOM (https://statistics.caricom.org/) or UN Comtrade for consistent HS-level series.', 0);
